+      _tty.childCorrupts();
+      return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
+    }
+    await _gate.future;
+    return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
+  }
+}
