+      // The child holds the tty open and leaves IXON re-enabled on exit.
+      _tty.childCorrupts();
+      return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
+    }
+    await _gate.future;
+    return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
+  }
+}
