+  /// The corrupting child: `stty ixon ixany < /dev/tty` mid-tool-phase.
+  void childCorrupts() {
+    enabled = {...enabled, 'ixon', 'ixany'};
+    events.add('child:stty-ixon-ixany');
+  }
