+      final tty = _FakeTty(); // post-boot: flags cleared
+      final guard = TermiosGuard(runner: tty.runner, hasTerminal: () => true);
+
+      // A child re-enables flow control mid-session (issue #735 repro).
+      tty.enabled = {'ixon', 'ixany'};
