+  /// When set, the `stty -a` probe exits non-zero (e.g. no /dev/tty).
+  bool failProbe;
+
+  /// When set, the flag-clear call exits non-zero (probe still works).
+  var failClear = false;
+
+  final calls = <List<String>>[];
