+    if (args.contains('-g')) return ProcessResult(0, 0, 'saved\n', '');
+    for (final arg in args) {
+      if (arg.startsWith('-')) {
+        enabled.remove(arg.substring(1));
+      }
+    }
+    return ProcessResult(0, 0, '', '');
+  }
